"""
Данные бестиария: виды, их уровни, земли, повадки, навыки, добыча и описание для Кодекса.
Модели — в gen_bestiary.py. Запуск генерации: python tools/gen_bestiary.py

temper: hostile — нападает сам; territorial — если подойти ближе `zone` блоков; neutral — только в ответ;
        timid — убегает; scavenger — нападает на раненых (здоровье < 60%).
traits: pack (зовёт стаю), flee_low (бежит при 25% здоровья), kite (держит дистанцию), blind (чует только
        шум: крадущийся игрок незаметен), disguise (притворяется предметом/растением), stealth (невидим до броска),
        drain (пьёт жизнь), regen, reflect (отражает снаряды), front_guard (щит спереди), split (делится),
        explode (взрыв при смерти), revive (встаёт один раз), enrage (ярость при 35%), aura_fire/aura_frost,
        engulf (затягивает в себя), sun_burn, flammable (огонь ×2), water (дышит под водой), fire_immune
skills: (вид, перезарядка в тиках, сила, дальность[, аргумент[, число]]):
        bolt (снаряд arg=вид), volley (n снарядов веером), arrows (n стрел), leap, charge, breath_fire/frost/poison,
        roar, howl, stomp, tongue, burrow, summon (arg=моб, n=сколько, r=максимум рядом), gaze, scream, blink, roots, swoop
"""


def S(id, ru, en, plural, level, size, hp, dmg, speed, *, armor=0, kb=0.0, fly=0.0, temper='hostile', zone=8, time='any',
      place='surface', group=(1, 1), weight=6, lands=(), traits=(), skills=(), hit=(), fire=0, sound=('', '', '', 1.0),
      particle='', drops=(), egg=(0x808080, 0x404040), mobtype='', desc=''):
    return dict(id=id, ru=ru, en=en, plural=plural, level=level, w=size[0], h=size[1], hp=hp, dmg=dmg, speed=speed, armor=armor,
                kb=kb, fly=fly, temper=temper, zone=zone, time=time, place=place, group=list(group), weight=weight, lands=list(lands),
                traits=list(traits),
                skills=[dict(s=k[0], cd=k[1], p=k[2], r=k[3], arg=(k[4] if len(k) > 4 else ''), n=(k[5] if len(k) > 5 else 1)) for k in skills],
                hit=[list(h) for h in hit], fire=fire, sound=list(sound), particle=particle, drops=[list(d) for d in drops],
                egg=list(egg), mobtype=mobtype, desc=desc)


def snd(prefix, pitch=1.0, amb=None, hurt=None, death=None):
    return ('minecraft:' + (amb or prefix + '.ambient'), 'minecraft:' + (hurt or prefix + '.hurt'),
            'minecraft:' + (death or prefix + '.death'), pitch)


